import itertools
def letterCombinations(digits):
    if not digits:
        return []
    M = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl', '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    return ["".join(p) for p in itertools.product(*[M[d] for d in digits])]

